var SUPABASE_ANON_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpmcnB2aWprZmNzZmV3dGxqbmFoIiwicm9sZSI6ImFub24iLCJpYXQiOjE3OTQ3MjIwODcsImV4cCI6MjExMDI5ODA4N30.p3KtKt4ml0Xn2gSlx_yzF4EKzIBwq_QxHt0VvVqKd5U';
var SUPABASE_RPC_URL = 'https://jfrpvijkfcsfewtljnah.supabase.co/rest/v1/rpc';

function rpc(fn, data) {
  return fetch(SUPABASE_RPC_URL + '/' + fn, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'apikey': SUPABASE_ANON_KEY,
      'Authorization': 'Bearer ' + SUPABASE_ANON_KEY
    },
    body: JSON.stringify(data || {})
  }).then(function (r) {
    return r.text();
  }).then(function (t) {
    try { return JSON.parse(t); } catch (e) { return { ok: false, err: t }; }
  });
}

function api(action, data) {
  data = data || {}; data.action = action; data.tok = A.tok;
  var p = window.MOCK ? MOCK(data) : fetch(API_URL, { method: 'POST', body: JSON.stringify(data) }).then(function (r) { return r.text(); }).then(function (t) {
    try { return JSON.parse(t); } catch (e) { throw new Error('সার্ভার থেকে ভুল উত্তর এসেছে। API লিংক ঠিক আছে কিনা দেখুন।'); }
  });
  return p.then(function (r) {
    if (r && r.auth === false) { A.tok = ''; LSs('ug_adm', null); render('login'); throw new Error(r.err); }
    return r;
  });
}
var _topProgressTimer = null;
function setTopProgress(pct) {
  var b = $('top-progress');
  if (!b) return;
  if (pct === 0) {
    b.style.opacity = '1';
    b.style.width = '0%';
  } else if (pct === 100) {
    b.style.width = '100%';
    setTimeout(function () {
      b.style.opacity = '0';
      setTimeout(function () { b.style.width = '0%'; }, 250);
    }, 200);
  } else {
    b.style.opacity = '1';
    b.style.width = pct + '%';
  }
}
function startTopProgress() {
  setTopProgress(18);
  clearInterval(_topProgressTimer);
  var current = 18;
  _topProgressTimer = setInterval(function () {
    if (current < 85) {
      current += Math.random() * 14;
      setTopProgress(Math.min(current, 85));
    }
  }, 140);
}
function finishTopProgress() {
  clearInterval(_topProgressTimer);
  setTopProgress(100);
}

function busy(on, text) {
  var el = $('loading');
  if (!el) return;
  var txt = $('loading-text');
  if (txt) txt.textContent = text || 'লোড হচ্ছে…';
  if (on) {
    startTopProgress();
    el.classList.add('show');
    el.style.display = 'flex';
  } else {
    finishTopProgress();
    el.classList.remove('show');
    setTimeout(function () {
      if (!el.classList.contains('show')) el.style.display = 'none';
    }, 220);
  }
}

function call(action, data, okMsg) {
  busy(1, 'প্রক্রিয়াধীন…');
  return api(action, data).then(function (r) { busy(0); if (!r.ok) { toast(r.err || 'সমস্যা হয়েছে', 1); throw new Error(r.err); } if (okMsg) toast(okMsg); return r; })
    .catch(function (e) { busy(0); if (e && e.message && !/সমস্যা|মেলেনি|মেয়াদ/.test(e.message) && !$('toast').classList.contains('show')) toast(e.message || 'সার্ভারে পৌঁছানো যাচ্ছে না', 1); throw e; });
}
function toast(m, err) { var t = $('toast'); t.textContent = m; t.className = 'toast show' + (err ? ' err' : ''); clearTimeout(t._t); t._t = setTimeout(function () { t.className = 'toast'; }, err ? 5000 : 2400); }
function load(tabs, force) {
  var need = tabs.filter(function (t) { return force || !A.data[t]; });
  if (!need.length) return Promise.resolve();
  startTopProgress();
  return api('a_data', { tabs: need }).then(function (r) {
    finishTopProgress();
    if (!r.ok) throw new Error(r.err);
    fixImgs(r);
    need.forEach(function (t) { A.data[t] = r[t] || []; });
    A.eps = r.eps;
    A.cloudinary = r.cloudinary;
    A.sms = r.sms;
    A.webapp = r.webapp;
  }).catch(function (e) {
    finishTopProgress();
    toast(e.message || 'লোড করা যায়নি', 1);
    throw e;
  });
}
function kv(t) { var o = {}; (A.data[t] || []).forEach(function (r) { o[r.key] = r.value; }); return o; }

