function modal(h, wide) { $('mbox').innerHTML = h; $('mbox').className = 'mbox' + (wide ? ' wide' : ''); $('mov').hidden = false; var f = $('mbox').querySelector('input,textarea'); if (f) setTimeout(function () { f.focus(); }, 50); }
