A.landingTab = A.landingTab || 'hero';
A.landingConfig = null;

function mergeLandingConfig(saved) {
  if (!saved || typeof saved !== 'object') saved = {};
  var def = JSON.parse(JSON.stringify(DEFAULT_LANDING_CONFIG));
  var res = Object.assign({}, def, saved);
  res.hero = Object.assign({}, def.hero, saved.hero || {});
  res.reviews_meta = Object.assign({}, def.reviews_meta, saved.reviews_meta || {});
  res.pricing = Object.assign({}, def.pricing, saved.pricing || {});
  res.pricing.features = Array.isArray(saved.pricing && saved.pricing.features) && saved.pricing.features.length ? saved.pricing.features : def.pricing.features;
  res.faqs_meta = Object.assign({}, def.faqs_meta, saved.faqs_meta || {});
  res.cta = Object.assign({}, def.cta, saved.cta || {});
  res.visibility = Object.assign({}, def.visibility, saved.visibility || {});
  res.reviews = Array.isArray(saved.reviews) && saved.reviews.length ? saved.reviews : def.reviews;
  res.faqs = Array.isArray(saved.faqs) && saved.faqs.length ? saved.faqs : def.faqs;
  res.pains = Array.isArray(saved.pains) && saved.pains.length ? saved.pains : def.pains;
  res.gallery = Array.isArray(saved.gallery) && saved.gallery.length ? saved.gallery : def.gallery;
  res.steps = Array.isArray(saved.steps) && saved.steps.length ? saved.steps : def.steps;
  return res;
}

P.landing = function () {
  if (A.landingConfig && A.landingConfig.hero && A.landingConfig.hero.title) {
    return Promise.resolve(drawLandingUi());
  }
  var postgrestUrl = 'https://jfrpvijkfcsfewtljnah.supabase.co/rest/v1/landing_config?id=eq.main&select=data';
  return fetch(postgrestUrl, {
    headers: {
      'apikey': K,
      'Authorization': 'Bearer ' + K
    }
  }).then(function (r) {
    if (!r.ok) throw new Error('PostgREST error ' + r.status);
    return r.json();
  }).then(function (arr) {
    var saved = (arr && arr[0] && arr[0].data) || null;
    A.landingConfig = mergeLandingConfig(saved);
    return drawLandingUi();
  }).catch(function (e) {
    if (A.data && A.data.settings) {
      var row = A.data.settings.find(function (s) { return s.key === 'landing_config'; });
      if (row && row.value) {
        try {
          A.landingConfig = mergeLandingConfig(JSON.parse(row.value));
          return drawLandingUi();
        } catch (err) {}
      }
    }
    A.landingConfig = mergeLandingConfig(null);
    return drawLandingUi();
  });
};

function drawLandingUi() {
  var cfg = A.landingConfig = mergeLandingConfig(A.landingConfig);
  var tab = A.landingTab || 'hero';
  var TABS = [
    ['hero', 'হিরো ব্যানার'],
    ['gallery', 'নমুনা ডিজাইন (' + BN(cfg.gallery.length) + ')'],
    ['steps', 'কীভাবে কাজ করে (' + BN(cfg.steps.length) + ')'],
    ['reviews', 'কাস্টমার রিভিউ (' + BN(cfg.reviews.length) + ')'],
    ['pricing', 'প্যাকেজ ও মূল্য'],
    ['faqs', 'প্রশ্নোত্তর (' + BN(cfg.faqs.length) + ')'],
    ['pains', 'সমস্যা ও সমাধান (' + BN(cfg.pains.length) + ')'],
    ['cta', 'শেষের ব্যানার'],
    ['visibility', 'সেকশন চালু/বন্ধ']
  ];

  var tabsHtml = '<div class="chips2" style="margin-bottom:16px">' + TABS.map(function (t) {
    return '<a class="chip' + (tab === t[0] ? ' on' : '') + '" onclick="setLandingTab(\'' + t[0] + '\')">' + t[1] + '</a>';
  }).join('') + '</div>';

  var contentHtml = '';
  if (tab === 'hero') contentHtml = landingHeroHtml(cfg.hero);
  else if (tab === 'gallery') contentHtml = landingGalleryHtml(cfg.gallery);
  else if (tab === 'steps') contentHtml = landingStepsHtml(cfg.steps);
  else if (tab === 'reviews') contentHtml = landingReviewsHtml(cfg.reviews_meta, cfg.reviews);
  else if (tab === 'pricing') contentHtml = landingPricingHtml(cfg.pricing);
  else if (tab === 'faqs') contentHtml = landingFaqsHtml(cfg.faqs_meta, cfg.faqs);
  else if (tab === 'pains') contentHtml = landingPainsHtml(cfg.pains);
  else if (tab === 'cta') contentHtml = landingCtaHtml(cfg.cta);
  else if (tab === 'visibility') contentHtml = landingVisibilityHtml(cfg.visibility);

  return ah('ল্যান্ডিং পেজ কন্ট্রোল (CMS)', 'পাবলিক ল্যান্ডিং পেজের প্রতিটা সেকশন, হিরো ব্যানার, ছবি, রিভিউ, প্যাকেজ ও প্রশ্নোত্তর সরাসরি এখান থেকে সাজান।', '<a class="btn sm sec" href="/" target="_blank">' + I.eye + 'লাইভ সাইট দেখুন ↗</a>') +
    '<div class="note2"><div>যেকোনো লেখায় <b>*তারকা চিহ্নের মাঝে*</b> শব্দ রাখলে সেটি ওয়েবসাইটে কমলা রঙে হাইলাইট হবে (যেমন: মাত্র *১ টাকায়* আপনার ডিজাইন)।</div></div>' +
    tabsHtml + '<div class="pn" id="landing-body">' + contentHtml + '</div>' + savebar('saveLandingConfig()');
}

function setLandingTab(t) {
  A.landingTab = t;
  var el = $('landing-body');
  if (el) {
    var cfg = A.landingConfig = mergeLandingConfig(A.landingConfig);
    var html = '';
    if (t === 'hero') html = landingHeroHtml(cfg.hero);
    else if (t === 'gallery') html = landingGalleryHtml(cfg.gallery);
    else if (t === 'steps') html = landingStepsHtml(cfg.steps);
    else if (t === 'reviews') html = landingReviewsHtml(cfg.reviews_meta, cfg.reviews);
    else if (t === 'pricing') html = landingPricingHtml(cfg.pricing);
    else if (t === 'faqs') html = landingFaqsHtml(cfg.faqs_meta, cfg.faqs);
    else if (t === 'pains') html = landingPainsHtml(cfg.pains);
    else if (t === 'cta') html = landingCtaHtml(cfg.cta);
    else if (t === 'visibility') html = landingVisibilityHtml(cfg.visibility);
    el.innerHTML = html;
    var chips = document.querySelectorAll('#am .chips2 .chip');
    var tabKeys = ['hero', 'gallery', 'steps', 'reviews', 'pricing', 'faqs', 'pains', 'cta', 'visibility'];
    chips.forEach(function (c, i) {
      if (tabKeys[i] === t) c.classList.add('on');
      else c.classList.remove('on');
    });
  } else {
    rer();
  }
}

